macro_rules! deps {
    () => {
        RingBuffer!();
        DropTest!();
    };
}

macro_rules! test {
    () => {
        deps!();
        # [cfg (test)] mod test { use super :: * ; # [test] fn validity_invariant () { assert ! (Some (RingBuffer ::< Box < () >, 64 >:: new ()) . is_some ()) ; } # [test] fn is_full () { let mut chunk = RingBuffer :: < _ , 64 > :: new () ; for i in 0 .. 64 { assert_eq ! (false , chunk . is_full ()) ; chunk . push_back (i) ; } assert_eq ! (true , chunk . is_full ()) ; } # [test] fn ref_iter () { let chunk : RingBuffer < i32 , 64 > = (0 .. 64) . collect () ; let out_vec : Vec < & i32 > = chunk . iter () . collect () ; let should_vec_p : Vec < i32 > = (0 .. 64) . collect () ; let should_vec : Vec < & i32 > = should_vec_p . iter () . collect () ; assert_eq ! (should_vec , out_vec) ; } # [test] fn mut_ref_iter () { let mut chunk : RingBuffer < i32 , 64 > = (0 .. 64) . collect () ; let out_vec : Vec < & mut i32 > = chunk . iter_mut () . collect () ; let mut should_vec_p : Vec < i32 > = (0 .. 64) . collect () ; let should_vec : Vec < & mut i32 > = should_vec_p . iter_mut () . collect () ; assert_eq ! (should_vec , out_vec) ; } # [test] fn consuming_iter () { let chunk : RingBuffer < i32 , 64 > = (0 .. 64) . collect () ; let out_vec : Vec < i32 > = chunk . into_iter () . collect () ; let should_vec : Vec < i32 > = (0 .. 64) . collect () ; assert_eq ! (should_vec , out_vec) ; } # [test] fn draining_iter () { let mut chunk : RingBuffer < i32 , 64 > = (0 .. 64) . collect () ; let mut half : RingBuffer < i32 , 64 > = chunk . drain () . take (16) . collect () ; half . extend (chunk . drain () . rev () . take (16)) ; let should : Vec < i32 > = (16 .. 48) . collect () ; assert_eq ! (chunk , should) ; let should : Vec < i32 > = (0 .. 16) . chain ((48 .. 64) . rev ()) . collect () ; assert_eq ! (half , should) ; } # [cfg (feature = "std")] # [test] fn io_write () { use std :: io :: Write ; let mut buffer : RingBuffer < u8 , 64 > = (0 .. 32) . collect () ; let to_write : Vec < u8 > = (32 .. 128) . collect () ; assert_eq ! (32 , buffer . write (& to_write) . unwrap ()) ; assert_eq ! (buffer , (0 .. 64) . collect ::< Vec < u8 >> ()) ; } # [cfg (feature = "std")] # [test] fn io_read () { use std :: io :: Read ; let mut buffer : RingBuffer < u8 , 64 > = (16 .. 48) . collect () ; let mut read_buf : Vec < u8 > = (0 .. 16) . collect () ; assert_eq ! (16 , buffer . read (& mut read_buf) . unwrap ()) ; assert_eq ! (read_buf , (16 .. 32) . collect ::< Vec < u8 >> ()) ; assert_eq ! (buffer , (32 .. 48) . collect ::< Vec < u8 >> ()) ; assert_eq ! (16 , buffer . read (& mut read_buf) . unwrap ()) ; assert_eq ! (read_buf , (32 .. 48) . collect ::< Vec < u8 >> ()) ; assert_eq ! (buffer , vec ! []) ; assert_eq ! (0 , buffer . read (& mut read_buf) . unwrap ()) ; } # [test] fn clone () { let buffer : RingBuffer < u32 , 64 > = (0 .. 50) . collect () ; assert_eq ! (buffer , buffer . clone ()) ; } # [test] fn failing () { let mut buffer : RingBuffer < u32 , 64 > = RingBuffer :: new () ; buffer . push_front (0) ; let mut add : RingBuffer < u32 , 64 > = vec ! [1 , 0 , 0 , 0 , 0 , 0] . into_iter () . collect () ; buffer . append (& mut add) ; assert_eq ! (1 , buffer . remove (1)) ; let expected = vec ! [0 , 0 , 0 , 0 , 0 , 0] ; assert_eq ! (buffer , expected) ; } use crate :: tests :: DropTest ; use std :: sync :: atomic :: { AtomicUsize , Ordering } ; # [test] fn dropping () { let counter = AtomicUsize :: new (0) ; { let mut chunk : RingBuffer < DropTest < '_ > , 64 > = RingBuffer :: new () ; for _i in 0 .. 20 { chunk . push_back (DropTest :: new (& counter)) } for _i in 0 .. 20 { chunk . push_front (DropTest :: new (& counter)) } assert_eq ! (40 , counter . load (Ordering :: Relaxed)) ; for _i in 0 .. 10 { chunk . pop_back () ; } assert_eq ! (30 , counter . load (Ordering :: Relaxed)) ; } assert_eq ! (0 , counter . load (Ordering :: Relaxed)) ; } # [test] # [should_panic (expected = "assertion failed: Self::CAPACITY >= 1")] fn unit_on_empty () { let _ = RingBuffer :: < usize , 0 > :: unit (1) ; } # [test] # [should_panic (expected = "assertion failed: Self::CAPACITY >= 2")] fn pair_on_empty () { let _ = RingBuffer :: < usize , 0 > :: pair (1 , 2) ; } }
    };
}

test!()